// الفصل الثالث: تنظيمُ البياناتِ وعرضُها وتفسيرُها (الصفّ الرابع)
import { AR, fmt, rnd, pick, shuf } from './mathkit.js';
import { $, $$, num, lst, mcq, ch, open, fld, star } from './engine.js';
import { chartBox, tallyTask, graphTask } from './stats.js';
import { T2, KB, LT, FOUR, cmpS, roundQ, placeQ } from './kit4.js';

const COL = ['#e85a4f', '#3a7ae0', '#2f8f4a', '#f2b818', '#8a4ad8', '#1aa3a3', '#c8407a', '#d07a10'];
const CN = { 'أحمر': '#e8413a', 'أزرق': '#3a7ae0', 'أخضر': '#2f9f4a', 'أصفر': '#f5c518', 'وردي': '#f38cc0', 'برتقالي': '#f08a24', 'بنفسجي': '#8a4ad8' };
/** قطاعاتٌ دائريّة: [[الاسم، القيمة، اللون؟]] */
export function pieSVG(data, o = {}) {
  const T = data.reduce((a, d) => a + d[1], 0); let a0 = -Math.PI / 2, g = '';
  data.forEach(([n, v, c], i) => { const a1 = a0 + 2 * Math.PI * v / T, big = a1 - a0 > Math.PI ? 1 : 0; const P = a => [150 + 110 * Math.cos(a), 150 + 110 * Math.sin(a)];
    const [x0, y0] = P(a0), [x1, y1] = P(a1); g += data.length === 1 ? `<circle cx="150" cy="150" r="110" fill="${c || COL[i]}"/>` : `<path d="M150 150 L${x0} ${y0} A110 110 0 ${big} 1 ${x1} ${y1}Z" fill="${c || COL[i % COL.length]}" stroke="#fff" stroke-width="2"/>`;
    const m = (a0 + a1) / 2, r = v / T < .12 ? 132 : 70, [tx, ty] = [150 + r * Math.cos(m), 150 + r * Math.sin(m)];
    g += `<text x="${tx}" y="${ty}" text-anchor="middle" font-size="${v / T < .12 ? 11 : 13}" font-weight="800" fill="${v / T < .12 ? '#222' : '#fff'}" style="paint-order:stroke;stroke:${v / T < .12 ? '#fff' : 'rgba(0,0,0,.25)'};stroke-width:2px">${n}${o.vals ? ' ' + AR(v) : ''}</text>`; a0 = a1; });
  return `<div style="text-align:center">${o.title ? `<b>${o.title}</b>` : ''}<svg viewBox="-10 0 320 300" style="max-width:300px;width:100%;display:block;margin:auto">${g}</svg></div>`;
}
/** مؤشّرٌ دوّار: قطاعاتٌ متساويةٌ أو بأوزان [[نص، لون، وزن؟]] */
export function spinSVG(secs, rot = 0) {
  const T = secs.reduce((a, s) => a + (s[2] || 1), 0); let a0 = -Math.PI / 2, g = '';
  secs.forEach(([t, c, w = 1]) => { const a1 = a0 + 2 * Math.PI * w / T, big = a1 - a0 > Math.PI ? 1 : 0, P = a => [100 + 90 * Math.cos(a), 100 + 90 * Math.sin(a)]; const [x0, y0] = P(a0), [x1, y1] = P(a1);
    g += secs.length === 1 ? `<circle cx="100" cy="100" r="90" fill="${c}"/>` : `<path d="M100 100 L${x0} ${y0} A90 90 0 ${big} 1 ${x1} ${y1}Z" fill="${c}" stroke="#333" stroke-width="1.5"/>`;
    const m = (a0 + a1) / 2; if (t) g += `<text x="${100 + 58 * Math.cos(m)}" y="${106 + 58 * Math.sin(m)}" text-anchor="middle" font-size="20" font-weight="900" fill="#222">${t}</text>`; a0 = a1; });
  return `<svg viewBox="0 0 200 200" style="width:170px;display:block;margin:6px auto">${g}<g class="arrow" style="transform-origin:100px 100px;transform:rotate(${rot}deg)"><line x1="100" y1="100" x2="100" y2="28" stroke="#222" stroke-width="5" stroke-linecap="round"/><path d="M100 18 l-9 16 h18z" fill="#222"/><circle cx="100" cy="100" r="7" fill="#fff" stroke="#222" stroke-width="3"/></g></svg>`;
}
/** كيسٌ من الكرات/المكعّبات الملوّنة */
export const bagHTML = (cols, shape = '●') => `<div style="display:inline-block;border:3px solid #9bb;border-radius:40% 40% 18px 18px;padding:14px 10px 8px;background:#f4fbff;max-width:220px;margin:6px auto;line-height:1.1;font-size:30px;text-align:center">${cols.map(([c, n]) => `<span style="color:${CN[c] || c}">${shape.repeat(n)}</span>`).join('')}</div>`;
const tallyStr = k => '𝍸'.repeat(Math.floor(k / 5)) + ' ' + '|'.repeat(k % 5);
const T3 = (head, rows) => T2(head, rows.map(r => r.map(x => typeof x === 'number' ? AR(x) : x)));
const freq = (head, data) => T3([head, 'الإشارات', 'التكرار'], data.map(([n, k]) => [n, tallyStr(k), k]));
const bar = (data, o) => chartBox(data, { labels: false, ...o });
const PROB = ['مؤكّد', 'أكثرُ احتمالًا', 'متساوي الإمكانيّة', 'أقلُّ احتمالًا', 'مستحيل'];
const pw = (tag, text, k, o = {}) => ch(tag, text, PROB, k, { skill: 'prob', ...o });
/** وصفُ الاحتمالِ بالأعداد: «a من n» */
const pn = (tag, text, a, n, o = {}) => fld(tag, text, [['عددُ النواتجِ المطلوبة', a], ['من أصل', n]], { skill: 'probn', sol: [`الاحتمال: ${AR(a)} من ${AR(n)}`], ...o });

const pwn = (tag, text, k, a, n, o = {}) => [pw(tag + ' (بالكلمات)', text, k, o), pn(tag + ' (بالأعداد)', text, a, n, o)];
/** أداةُ تجربةِ المؤشّر: تدويرٌ وتسجيلُ النتائجِ بالإشارات */
function spinLab(secs) { return el => {
  const T = secs.reduce((a, s) => a + (s[2] || 1), 0); const c = {}; secs.forEach(s => c[s[0]] = 0); let rot = 0, busy = false;
  const table = () => T3(['الناتج', 'الإشارات', 'التكرار'], secs.map(s => [s[0], tallyStr(c[s[0]]), c[s[0]]]));
  el.innerHTML = `<div class="row c"><div class="sp">${spinSVG(secs)}</div><div><button class="btn" data-a="s1">🎡 دوّرْ مرّة</button> <button class="btn s" data-a="s10">١٠ مرّات</button><div class="res"></div></div></div><div class="tt">${table()}</div><div class="meta">لاحظْ: القطاعُ الأكبرُ يتوقّفُ عنده المؤشّرُ أكثر.</div>`;
  const one = () => { let r = Math.random() * T, k = 0; while (r > (secs[k][2] || 1)) { r -= secs[k][2] || 1; k++; } const before = secs.slice(0, k).reduce((a, s) => a + (s[2] || 1), 0); const ang = (before + r) / T * 360; return [k, ang]; };
  const spin = n => { if (busy) return; busy = true; let i = 0; const step = () => { const [k, ang] = one(); rot = Math.ceil(rot / 360) * 360 + 720 + ang; const ar = $('.arrow', el); ar.style.transition = n > 1 ? 'transform .25s' : 'transform 1.2s cubic-bezier(.2,.8,.3,1)'; ar.style.transform = `rotate(${rot}deg)`;
      setTimeout(() => { c[secs[k][0]]++; $('.tt', el).innerHTML = table(); $('.res', el).innerHTML = `توقّفَ عندَ: <b>${secs[k][0]}</b>`; if (++i < n) step(); else busy = false; }, n > 1 ? 300 : 1250); }; step(); };
  $('[data-a="s1"]', el).onclick = () => spin(1); $('[data-a="s10"]', el).onclick = () => spin(10);
}; }

/* ═════════ المولّدات ═════════ */
const NAMES = ['التفاح', 'الموز', 'البرتقال', 'العنب', 'المانجو'], SP = ['كرة القدم', 'السباحة', 'الجري', 'كرة السلّة'];
const G = {
  tally: L => { const ks = shuf(NAMES).slice(0, 3 + (L > 0)); const items = shuf(ks.flatMap(k => Array(rnd(1, 4 + 2 * L)).fill(k))); const names = Object.fromEntries(ks.map(k => [k, k])); return { ...tallyTask('', 'نظّمِ البياناتِ في لوحةِ إشاراتٍ وجدولٍ تكراريّ: سُئلَ طلابٌ عن فاكهتِهم المفضّلة.', items, names, { head: 'الفاكهة' }) }; },
  bar: L => { const ks = shuf(SP).slice(0, 4); const step = pick([1, 2, 5, 10]); const d = ks.map(k => [k, step * rnd(1, 8)]); const k = rnd(0, 1); const sorted = d.slice().sort((a, b) => b[1] - a[1]);
    if (sorted[0][1] === sorted[1][1]) d[0][1] += step * 9;
    const s2 = d.slice().sort((a, b) => b[1] - a[1]);
    return k ? mcq('', 'استعملِ التمثيلَ بالأعمدة: ما الرياضةُ الأكثرُ تفضيلًا؟', ks, ks.indexOf(s2[0][0]), { skill: 'bar', html: bar(d, { title: 'الرياضةُ المفضّلة', y: 'عددُ الطلاب', step }) }) : num('', `استعملِ التمثيلَ بالأعمدة: كم يزيدُ عددُ من يفضّلونَ ${d[0][0]} على من يفضّلونَ ${d[1][0]}؟ (اكتبِ الفرقَ موجبًا)`, Math.abs(d[0][1] - d[1][1]), { skill: 'bar', html: bar(d, { title: 'الرياضةُ المفضّلة', y: 'عددُ الطلاب', step }), sol: [`${AR(Math.max(d[0][1], d[1][1]))} − ${AR(Math.min(d[0][1], d[1][1]))} = ${AR(Math.abs(d[0][1] - d[1][1]))}`] }); },
  line: L => { const days = ['السبت', 'الأحد', 'الاثنين', 'الثلاثاء', 'الأربعاء']; const d = days.map(x => [x, 10 * rnd(2, 9)]); const mx = Math.max(...d.map(x => x[1])), mn = Math.min(...d.map(x => x[1]));
    return num('', 'التمثيلُ بالخطوطِ يبيّنُ عددَ زوّارِ المكتبةِ في أيّامِ الأسبوع. ما الفرقُ بينَ أكبرِ عددٍ وأقلِّ عددٍ من الزوّار؟', mx - mn, { skill: 'line', html: chartBox(d, { kind: 'line', title: 'زوّارُ المكتبة', y: 'عددُ الزوّار', labels: true, step: 10 }), sol: [`${AR(mx)} − ${AR(mn)} = ${AR(mx - mn)}`] }); },
  pie: L => { const T = pick([40, 80, 100, 200]); const parts = [T / 2, T / 4, T / 8, T / 8]; const ns = shuf(['الحليب', 'العصير', 'الماء', 'اللبن']); const d = ns.map((n, i) => [n, parts[i]]);
    return pick([mcq('', 'التمثيلُ بالقطاعاتِ الدائريّةِ يبيّنُ المشروبَ المفضّل. ما المشروبُ الذي يفضّلُه نصفُ الطلاب؟', ns, 0, { skill: 'pie', html: pieSVG(d) }), mcq('', 'ما المشروبُ الذي يمثّلُ ربعَ الدائرة؟', ns, 1, { skill: 'pie', html: pieSVG(d) })]); },
  prob: L => { const cols = shuf(['أحمر', 'أزرق', 'أخضر', 'أصفر']); const n = [rnd(4, 7), rnd(1, 3), 0, 0]; n[2] = n[1]; const bag = [[cols[0], n[0]], [cols[1], n[1]], [cols[2], n[2]]]; const tot = n[0] + n[1] + n[2];
    return pick([pw('', `صِفِ احتمالَ سحبِ كرةٍ ${cols[0] === 'أحمر' ? 'حمراء' : cols[0] === 'أزرق' ? 'زرقاء' : cols[0] === 'أخضر' ? 'خضراء' : 'صفراء'} من الكيس.`, 1, { html: bagHTML(bag) }), pw('', `صِفِ احتمالَ سحبِ كرةٍ ${cols[3] === 'أحمر' ? 'حمراء' : cols[3] === 'أزرق' ? 'زرقاء' : cols[3] === 'أخضر' ? 'خضراء' : 'صفراء'} من الكيس.`, 4, { html: bagHTML(bag) }),
      pn('', `استعملِ الأعدادَ لوصفِ احتمالِ سحبِ كرةٍ لونُها ${cols[1]}.`, n[1], tot, { html: bagHTML(bag) })]); },
  table: L => { const a = rnd(2, 5), b = rnd(5, 12), k = rnd(4, 9); return num('', `أنشئْ جدولًا: يرافقُ كلَّ ${AR(b)} طلابٍ ${AR(a)} معلّمين. إذا كان عددُ المعلّمينَ ${AR(a * k)}، فما عددُ الطلاب؟`, b * k, { skill: 'table', sol: [T3(['المعلّمون', ...Array.from({ length: k }, (_, i) => a * (i + 1))], [['الطلاب', ...Array.from({ length: k }, (_, i) => b * (i + 1))]])] }); },
};
const GN = { tally: 'لوحة الإشارات والجدول التكراري', bar: 'التمثيل بالأعمدة', line: 'التمثيل بالخطوط', pie: 'القطاعات الدائرية', prob: 'الاحتمال', table: 'إنشاء جدول' };
