const TRIP = T3(['عددُ المعلّمين', 2, 4, 6, 8, 10, 12, 14, 16], [['عددُ الطلاب', 9, 18, 27, 36, 45, 54, 63, 72]]);
function tableTool(el) {
  el.innerHTML = `<div class="row">كلّ <input class="ans" data-kp="num" inputmode="none" style="width:60px" value="٢"> معلّمَين ← <input class="ans" data-kp="num" inputmode="none" style="width:60px" value="٩"> طلاب، حتى <input class="ans" data-kp="num" inputmode="none" style="width:60px" value="١٦"> معلّمًا <button class="btn sm">أنشئِ الجدول</button></div><div class="tout"></div>`;
  const P = s => +String(s).replace(/[٠-٩]/g, c => '٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/\D/g, '');
  const go = () => { const [a, b, m] = $$('input', el).map(i => P(i.value)); if (!(a > 0 && b > 0 && m >= a) || m / a > 14) { $('.tout', el).innerHTML = '<div class="meta">اكتبْ أعدادًا مناسبة.</div>'; return; } const k = Math.floor(m / a);
    $('.tout', el).innerHTML = T3(['المعلّمون', ...Array.from({ length: k }, (_, i) => a * (i + 1))], [['الطلاب', ...Array.from({ length: k }, (_, i) => b * (i + 1))]]) + `<div class="keybox">النمط: نضيفُ ${AR(a)} إلى المعلّمين، و${AR(b)} إلى الطلاب في كلِّ مرّة.</div>`; };
  $('button', el).onclick = go; go();
}
